"""Immutable r15 from r14: stopbeacon only after actual scan admission."""
import argparse,difflib,hashlib,json,shutil
from pathlib import Path
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser();p.add_argument('--parent',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();assert not a.output.exists();proof=json.loads((a.parent/'result.json').read_text());a.output.mkdir(parents=True)
 for rel,h in proof['changed_sources'].items():assert sha(a.parent/rel)==h
 shutil.copytree(a.parent/'source',a.output/'source');shutil.copytree(a.parent/'headers',a.output/'headers');rel='source/wlan/ieee80211_scan.c';f=a.output/rel;old=f.read_text();needle='if (vap->iv_opmode == IEEE80211_M_HOSTAP\n#ifdef QTN_BG_SCAN\n\t\t\t&& !(flags & IEEE80211_SCAN_QTN_BGSCAN)';assert old.count(needle)==1;new=old.replace(needle,'if (om_start_owned && vap->iv_opmode == IEEE80211_M_HOSTAP\n#ifdef QTN_BG_SCAN\n\t\t\t&& !(flags & IEEE80211_SCAN_QTN_BGSCAN)',1);f.write_text(new,newline='\n');patch=''.join(difflib.unified_diff(old.splitlines(True),new.splitlines(True),fromfile='a/'+rel,tofile='b/'+rel));(a.output/'chanset461-kernel.patch').write_text(patch,newline='\n');shutil.copyfile(a.parent/'chanset461-kernel.patch',a.output/'chanset461-parent-r14.patch');shutil.copyfile(a.parent/'chanset461-parent-r13.patch',a.output/'chanset461-parent-r13.patch');proof['changed_sources']=dict(proof['changed_sources']);proof['changed_sources'][rel]=sha(f);proof.update(derived_parent=str(a.parent.resolve()),derived_parent_result_sha256=sha(a.parent/'result.json'),patch_scope='EXACT_INCREMENTAL_R14_TO_R15',patch_sha256=sha(a.output/'chanset461-kernel.patch'),changed_variable='HostAPbeacon stop gated on localactual admission for typedandlegacy starts.',status='SOURCE_ONLY_CHANSET461_R15_LOCAL_ADMISSION_BEACON_GATE_PENDING_FIXTURE_ARC');proof['corrections']=list(proof['corrections'])+['Rejectedotherowner/busy scanstart never invokesbeaconstop; localadmittedstart invokesonce.'];(a.output/'result.json').write_text(json.dumps(proof,indent=2)+'\n');print(json.dumps({'status':proof['status'],'source_sha256':sha(f),'patch_sha256':proof['patch_sha256']},indent=2))
if __name__=='__main__':main()
